10	// 本文件为日内亏损保护补充回归保障：调用方补齐行情缺口、一次使多条报价连续
11	// 生效时，链中判断必须按“前一条报价实际产生后的状态”逐条承接。
12	//
13	// 关键构造：账户已开日、尚未触线并持有合约仓位，同时保留待成交买单、部分
14	// 成交买单与有效卖单；后续序号的报价先到并等待，再提交缺失报价，使同一批
15	// 报价中先出现触线价格，随后出现恢复价格（成功路径）或无法完成估值的天价
16	// （溢出回滚路径）。
17	//
18	// 成功路径要求：即使批末价格恢复、当前亏损回到上限以下，中间报价一旦触线，
19	// 日内限制整日保留；全部仍有效买单按编号从大到小撤销，部分成交买单只释放
20	// 未成交部分，已入账现金与持仓不变，卖单及其可卖数量占用不受影响；最新报价
21	// 推进到批末，当前净值按最后生效报价计算；触线记录固化在真正触线的中间时点。
22	//
23	// 失败路径要求：链末报价使持仓市值或“现金 + 市值”净值溢出 int64 时，整批
24	// 返回包装 ErrInt64Overflow 的错误与零条生效结果；最新报价、当日基准、亏损
25	// 上限与限制状态全部保留，链中本拟触发的撤单不得改变任何订单、现金占用、
26	// 持仓或卖单占用；原先等待的报价继续等待；只新增一条说明估值溢出的拒绝记录。
27	
28	// riskGapSetup 构造共用前置状态：
29	// 初始现金 1000，A 合约 10 股 @10 已成交入账（cash=900, pos=10, seq1@10）。
30	// 开日（日号 1，亏损上限 50，基准 1000）后再：
31	//   - bPending：A 待成交买单 3 股限价 9（现金占用 27，编号在后）
32	//   - bPartial：A 买单 4 股限价 8 并部分成交 2 股 @8
33	//     （cash=884, pos=12, 剩余 2 股占用现金 16）
34	//   - sellID：A 有效卖单 2 股限价 5（占用可卖数量 2）
35	//
36	// 返回引擎与三个订单编号；此时现金占用合计 43，可卖数量 10。
37	func riskGapSetup(t *testing.T) (e *Engine, bPending, bPartial, sellID int64) {
38		t.Helper()
39		e, _ = NewEngine(1000)
40		mustSetMax(t, e, "A", 100)
41		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
42		bid := mustBuy(t, e, "A", 10, 10)
43		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
44			t.Fatal(err)
45		}
46		if err := e.StartTradingDay(1, 50); err != nil {
47			t.Fatal(err)
48		}
49		bPending = mustBuy(t, e, "A", 3, 9)
50		bPartial = mustBuy(t, e, "A", 4, 8)
51		if _, err := e.Fill(Trade{TradeID: 2, OrderID: bPartial, Symbol: "A", Side: Buy, Price: 8, Qty: 2}); err != nil {
52			t.Fatal(err)
53		}
54		sellID = mustSell(t, e, "A", 2, 5)
55	
56		if e.Cash() != 884 || e.ReservedCash() != 43 || e.Position("A") != 12 || e.Sellable("A") != 10 {
57			t.Fatalf("前置状态错误: cash=%d reserved=%d pos=%d sellable=%d",
58				e.Cash(), e.ReservedCash(), e.Position("A"), e.Sellable("A"))
59		}
60		return e, bPending, bPartial, sellID
61	}
